const bool bIsParticleDynamic = (PBDParticle->ObjectState() == EObjectStateType::Dynamic);
const bool bIsParticleFrozenDuringBubbleResim = (PBDParticle->ResimType() == EResimType::FrozenDuringResim);
// We only integrate dynamic particles
// and when we are resimming, if bubble resim is enabled, we skip integrating particles frozen during resim
bool bShouldIntegrate = bIsParticleDynamic && !(bIsResimming && bIsBubbleResimEnabled && bIsParticleFrozenDuringBubbleResim);
if (bShouldIntegrate)
{
	FPBDRigidParticleHandle& Particle = *PBDParticle;

	FVec3 V = Particle.GetV();
	FVec3 W = Particle.GetW();

	//save off previous velocities
	Particle.SetPreV(V);
	Particle.SetPreW(W);

	for (FForceRule ForceRule : ForceRules)
	{
		ForceRule(Particle, Dt);
	}

	//EulerStepVelocityRule.Apply(Particle, Dt);
	V += Particle.Acceleration() * Dt;
	W += Particle.AngularAcceleration() * Dt;

	//AddImpulsesRule.Apply(Particle, Dt);
	V += Particle.LinearImpulseVelocity();
	W += Particle.AngularImpulseVelocity();
	Particle.LinearImpulseVelocity() = FVec3(0);
	Particle.AngularImpulseVelocity() = FVec3(0);

	//EtherDragRule.Apply(Particle, Dt);

	const FReal LinearDrag = LinearEtherDragOverride >= 0 ? LinearEtherDragOverride : Particle.LinearEtherDrag() * Dt;
	const FReal LinearMultiplier = FMath::Max(FReal(0), FReal(1) - LinearDrag);
	V *= LinearMultiplier;

	const FReal AngularDrag = AngularEtherDragOverride >= 0 ? AngularEtherDragOverride : Particle.AngularEtherDrag() * Dt;
	const FReal AngularMultiplier = FMath::Max(FReal(0), FReal(1) - AngularDrag);
	W *= AngularMultiplier;

	// Apply gyroscopic as a velocity change. This could be applied before the clamps, or after,
	// but the user might be surprised to see an angular velocity that exceeds the clamp
	// so do it before.
	if (Particle.GyroscopicTorqueEnabled())
	{
		W = Utilities::GetAngularVelocityAdjustedForGyroscopicTorques(Particle.RCom(), Particle.I(), W, Dt);
	}

	FReal LinearSpeedSq = V.SizeSquared();
	if (LinearSpeedSq > Particle.MaxLinearSpeedSq())
	{
		V *= FMath::Sqrt(Particle.MaxLinearSpeedSq() / LinearSpeedSq);
	}

	FReal AngularSpeedSq = W.SizeSquared();
	if (AngularSpeedSq > Particle.MaxAngularSpeedSq())
	{
		W *= FMath::Sqrt(Particle.MaxAngularSpeedSq() / AngularSpeedSq);
	}

	if (CVars::HackMaxAngularVelocity >= 0.f)
	{
		AngularSpeedSq = W.SizeSquared();
		if (AngularSpeedSq > HackMaxAngularSpeedSq)
		{
			W = W * (CVars::HackMaxAngularVelocity / FMath::Sqrt(AngularSpeedSq));
		}
	}

	if (CVars::HackMaxVelocity >= 0.f)
	{
		LinearSpeedSq = V.SizeSquared();
		if (LinearSpeedSq > HackMaxLinearSpeedSq)
		{
			V = V * (CVars::HackMaxVelocity / FMath::Sqrt(LinearSpeedSq));
		}
	}

	FVec3 PCoM = Particle.XCom();
	FRotation3 QCoM = Particle.RCom();

	PCoM = PCoM + V * Dt;
	QCoM = FRotation3::IntegrateRotationWithAngularVelocity(QCoM, W, Dt);

	Particle.SetTransformPQCom(PCoM, QCoM);
	Particle.SetV(V);
	Particle.SetW(W);

	 * Return a new rotation equal to the input rotation with angular velocity W applied over time Dt.
	 *
	 * Uses the relation: DQ/DT = (W * Q)/2
	 */
	TRotation<FReal, 3> TRotation<FReal, 3>::IntegrateRotationWithAngularVelocity(const TRotation<FReal, 3>& InR0, const TVector<FReal, 3>& InW, const FReal InDt)
	{
		TRotation<FReal, 3> R1 = InR0 + (TRotation<FReal, 3>::FromElements(InW.X, InW.Y, InW.Z, 0.f) * InR0) * decltype(InR0.X)(InDt * 0.5f);
		return R1.GetNormalized();
	}

	TRotation<FRealSingle, 3> TRotation<FRealSingle, 3>::IntegrateRotationWithAngularVelocity(const TRotation<FRealSingle, 3>& InR0, const TVector<FRealSingle, 3>& InW, const FRealSingle InDt)
	{
		TRotation<FRealSingle, 3> R1 = InR0 + (TRotation<FRealSingle, 3>::FromElements(InW.X, InW.Y, InW.Z, 0.f) * InR0) * decltype(InR0.X)(InDt * 0.5f);
		return R1.GetNormalized();
	}

}

    diagnostics.integrate_velocities += start.elapsed();
}

/// Integrates the positions of bodies based on their velocities and the time step.
pub fn integrate_positions(
    mut solver_bodies: Query<&mut SolverBody, Without<CustomPositionIntegration>>,
    time: Res<Time>,
    mut diagnostics: ResMut<SolverDiagnostics>,
) {
    let start = crate::utils::Instant::now();

    let delta_secs = time.delta_seconds_adjusted();

    solver_bodies.par_iter_mut().for_each(|body| {
        let SolverBody {
            linear_velocity,
            angular_velocity,
            delta_position,
            delta_rotation,
            ..
        } = body.into_inner();

        *delta_position += *linear_velocity * delta_secs;
        #[cfg(feature = "2d")]
        {
            // Note: We should probably use `add_angle_fast` here
            *delta_rotation = Rotation::radians(*angular_velocity * delta_secs) * *delta_rotation;
        }
        #[cfg(feature = "3d")]
        {
            delta_rotation.0 =
                Quaternion::from_scaled_axis(*angular_velocity * delta_secs) * delta_rotation.0;
        }
    });

fn run_substep_schedule(world: &mut World) {
    let delta = world.resource::<Time<Physics>>().delta();
    let SubstepCount(substeps) = *world.resource::<SubstepCount>();
    let sub_delta = delta.div_f64(substeps as f64);

    let mut sub_delta_time = world.resource_mut::<Time<Substeps>>();
    sub_delta_time.advance_by(sub_delta);

    let _ = world.try_schedule_scope(SubstepSchedule, |world, schedule| {
        for i in 0..substeps {
            trace!("running SubstepSchedule: {i}");
            *world.resource_mut::<Time>() = world.resource::<Time<Substeps>>().as_generic();
            schedule.run(world);
        }
    });

